"use client";

import { useId, useRef, type ReactElement } from "react";

import { IconClose, IconInfo } from "@rhs-ui/icons";
import { RecommendationReasonPanel } from "@rhs-ui/application/recommendation-reason-popover/panel";
import { DEFAULT_LABELS, type RecommendationReason, type RecommendationReasonLabels, type Sponsorship } from "@rhs-ui/application/recommendation-reason-popover/reasons";
import { Popover, PopoverClose, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { ReasonKind, RecommendationReason, RecommendationReasonLabels, Sponsorship } from "@rhs-ui/application/recommendation-reason-popover/reasons";
export { RecommendationReasonPanel, type RecommendationReasonPanelProps } from "@rhs-ui/application/recommendation-reason-popover/panel";

export interface RecommendationReasonPopoverProps {
  /** The reasons, in plain language, most important first: a sentence, an optional second line and the kind of signal. */
  reasons: readonly RecommendationReason[];
  /** Set for an ad: who paid, and what that means. The panel says so before anything else. */
  sponsored?: Sponsorship;
  /** Asks for less of this kind of thing. Return a promise and the row shows a spinner, then its confirmation in place; if it rejects the row goes back and says why. Leave it out for no such button. */
  onLessLikeThis?: () => void | Promise<void>;
  /** Hides this item. Same as above. Leave it out for no such button. */
  onHide?: () => void | Promise<void>;
  /** Where the settings for personalisation live. Leave it out for no link. */
  settingsHref?: string;
  /** The element that opens the panel, one button. Name it "Why am I seeing this?". Default: a small info button with that name. */
  trigger?: ReactElement;
  /** The heading of the panel, and the name of the default button. Default "Why am I seeing this?" */
  title?: string;
  /** Whether the popover is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The side of the button the panel opens on. It moves to another side when there is no room. Default "bottom". */
  side?: "top" | "right" | "bottom" | "left";
  /** How the panel lines up with the button along that side. Default "end", for a button at the end of a row. */
  align?: "start" | "center" | "end";
  /** The words the popover says, for translation. */
  labels?: RecommendationReasonLabels;
  /** Classes for the panel, for a different width. */
  className?: string;
}

/**
 * The answer to "why am I seeing this?", beside a recommendation, an ad or a ranked entry in a feed. A small info button
 * opens a panel that keeps the explanation out of the page until it is asked for: an ad says that it is one and who paid,
 * then the reasons come as short sentences in plain language with the kind of signal behind each, and real buttons let
 * people see less of it, hide it, or open their settings, with a confirmation in the button's own place. It is a
 * non-modal popover, so it works with a finger, a keyboard and a screen reader; Escape or a click outside closes it and
 * the focus goes back to the button.
 */
export function RecommendationReasonPopover({
  reasons,
  sponsored,
  onLessLikeThis,
  onHide,
  settingsHref,
  trigger,
  title,
  open,
  defaultOpen,
  onOpenChange,
  side = "bottom",
  align = "end",
  labels,
  className,
}: RecommendationReasonPopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const heading = title ?? words.title;
  const titleId = useId();
  const panel = useRef<HTMLDivElement>(null);

  return (
    <Popover open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        {trigger ?? (
          <button
            type="button"
            data-slot="recommendation-reason-trigger"
            aria-label={heading}
            className={cn(
              "relative inline-flex size-7 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none",
              "transition-[background-color,color] duration-150 motion-reduce:transition-none",
              "hover:bg-muted hover:text-foreground data-[state=open]:bg-muted data-[state=open]:text-foreground",
              "focus-visible:ring-[3px] focus-visible:ring-ring/40",
              // A bigger target on a touch screen without moving anything: the button grows by an invisible frame.
              "before:absolute before:-inset-1 before:content-[''] pointer-coarse:before:-inset-2",
            )}
          >
            <IconInfo size={16} />
          </button>
        )}
      </PopoverTrigger>
      <PopoverContent
        ref={panel}
        data-slot="recommendation-reason-popover"
        side={side}
        align={align}
        sideOffset={8}
        collisionPadding={12}
        tabIndex={-1}
        aria-labelledby={titleId}
        // Focus starts on the panel itself, so a screen reader reads its name and the first Tab lands on the first action; not on the close button.
        onOpenAutoFocus={(focus) => {
          focus.preventDefault();
          panel.current?.focus({ preventScroll: true });
        }}
        // The panel is never taller than the room there is: on a small screen it scrolls inside itself instead of running off the edge, and the close button stays in view.
        className={cn(
          "relative w-80 max-w-[min(20rem,var(--radix-popover-content-available-width))] max-h-(--radix-popover-content-available-height) scroll-pt-12 overflow-x-hidden overflow-y-auto overscroll-contain p-0 [scrollbar-color:color-mix(in_oklab,var(--foreground)_28%,transparent)_transparent] [scrollbar-width:thin]",
          className,
        )}
      >
        <RecommendationReasonPanel
          reasons={reasons}
          sponsored={sponsored}
          onLessLikeThis={onLessLikeThis}
          onHide={onHide}
          settingsHref={settingsHref}
          title={heading}
          labels={labels}
          titleId={titleId}
          close={
            <PopoverClose asChild>
              <button
                type="button"
                aria-label={words.close}
                className="inline-flex size-8 shrink-0 items-center justify-center rounded-md bg-popover text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none pointer-coarse:size-10"
              >
                <IconClose size={16} />
              </button>
            </PopoverClose>
          }
        />
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useId, useRef, useState, type ComponentProps, type ReactNode } from "react";

import {
  IconAlertCircle,
  IconCheck,
  IconChevronRight,
  IconCompass,
  IconEyeOff,
  IconHistory,
  IconMegaphone,
  IconPin,
  IconSliders,
  IconSpinner,
  IconTarget,
  IconThumbsDown,
  IconTrendUp,
  IconUserCheck,
  IconUsers,
} from "@rhs-ui/icons";
import {
  DEFAULT_KINDS,
  DEFAULT_LABELS,
  fill,
  isThenable,
  messageOf,
  type ReasonKind,
  type RecommendationReason,
  type RecommendationReasonLabels,
  type Sponsorship,
} from "@rhs-ui/application/recommendation-reason-popover/reasons";
import { Badge } from "@rhs-ui/primitives/badge";
import { cn } from "@/lib/utils";

export interface RecommendationReasonPanelProps extends Omit<ComponentProps<"div">, "title" | "children"> {
  /** The reasons, in plain language, most important first. */
  reasons: readonly RecommendationReason[];
  /** Set for an ad: who paid, and what that means. The panel says so first. */
  sponsored?: Sponsorship;
  /** Asks for less of this kind of thing. Return a promise and the row shows a spinner, then its confirmation; if it rejects the row goes back and says why. Leave it out for no such button. */
  onLessLikeThis?: () => void | Promise<void>;
  /** Hides this item. Same as above. Leave it out for no such button. */
  onHide?: () => void | Promise<void>;
  /** Where the settings for personalisation live. Leave it out for no link. */
  settingsHref?: string;
  /** The heading. Default "Why am I seeing this?" */
  title?: string;
  /** The words the panel says, for translation. */
  labels?: RecommendationReasonLabels;
  /** The element that closes the panel, drawn beside the title. The popover puts its close button here. */
  close?: ReactNode;
  /** The id of the title, so a dialog can be named by it. */
  titleId?: string;
}

/** The failure text, darkened toward the foreground so small red words reach 4.5:1. */
const DANGER_TEXT = "text-[color:color-mix(in_oklch,var(--destructive),var(--foreground)_30%)]";

const KIND_ICON = {
  activity: IconHistory,
  interest: IconTarget,
  popular: IconTrendUp,
  location: IconPin,
  similar: IconUsers,
  following: IconUserCheck,
  context: IconCompass,
} as const satisfies Record<ReasonKind, unknown>;

/** A row at the foot that is a real button: it asks, spins while it saves, and then says what it did, in its own place. */
const ROW = [
  "group/row flex min-h-9 w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-left text-sm outline-none",
  "transition-colors duration-150 motion-reduce:transition-none hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/40",
  "aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
].join(" ");

type Phase = "idle" | "pending" | "done";

function ActionRow({ icon, label, done, phase, onPress }: { icon: ReactNode; label: string; done: string; phase: Phase; onPress: () => void }) {
  return (
    <button type="button" aria-disabled={phase !== "idle" || undefined} aria-busy={phase === "pending" || undefined} onClick={onPress} className={cn(ROW, phase === "done" && "text-muted-foreground")}>
      <span aria-hidden="true" className={cn("grid size-4 place-items-center", phase === "idle" && "text-muted-foreground")}>
        {phase === "pending" ? <IconSpinner /> : phase === "done" ? <IconCheck className="text-foreground" /> : icon}
      </span>
      <span className="min-w-0 flex-1 leading-snug text-pretty">{phase === "done" ? done : label}</span>
    </button>
  );
}

/**
 * The explanation itself, as the content of a card: an ad says it is one first and who paid; then the reasons in plain
 * words with the kind of signal behind each; then real buttons to see less of this or to hide it, which confirm in their
 * own place, and a link to the settings. It is what RecommendationReasonPopover shows, usable by itself in a sheet or a
 * page about how recommendations work.
 */
export function RecommendationReasonPanel({
  reasons,
  sponsored,
  onLessLikeThis,
  onHide,
  settingsHref,
  title,
  labels,
  close,
  titleId,
  className,
  ...props
}: RecommendationReasonPanelProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const kinds: Record<ReasonKind, string> = { ...DEFAULT_KINDS, ...labels?.kinds };
  const ownTitleId = useId();
  const [less, setLess] = useState<Phase>("idle");
  const [hidden, setHidden] = useState<Phase>("idle");
  const [problem, setProblem] = useState("");
  const [said, setSaid] = useState("");
  const working = useRef(false);

  async function run(handler: (() => void | Promise<void>) | undefined, phase: Phase, setPhase: (next: Phase) => void, done: string) {
    if (!handler || working.current || phase !== "idle") return;
    setProblem("");
    setSaid("");
    let outcome: void | Promise<void>;
    try {
      outcome = handler();
    } catch (error) {
      fail(error);
      return;
    }
    // An answer that is already here needs no busy state; a promise shows a spinner while it runs.
    if (!isThenable(outcome)) {
      setPhase("done");
      setSaid(done);
      return;
    }
    working.current = true;
    setPhase("pending");
    setSaid(words.saving);
    try {
      await outcome;
      setPhase("done");
      setSaid(done);
    } catch (error) {
      setPhase("idle");
      fail(error);
    } finally {
      working.current = false;
    }
  }

  function fail(error: unknown) {
    const extra = messageOf(error);
    const message = extra ? `${words.failed} ${extra}` : words.failed;
    setProblem(message);
    setSaid(message);
  }

  const hasActions = Boolean(onLessLikeThis || onHide || settingsHref);

  return (
    <div data-slot="recommendation-reason-panel" data-sponsored={sponsored ? "" : undefined} className={cn("relative flex min-w-0 flex-col text-sm text-popover-foreground", className)} {...props}>
      <div className={cn("px-4 pt-4", close ? "pr-12" : undefined)}>
        <h3 id={titleId ?? ownTitleId} className="text-[0.9375rem] leading-snug font-semibold tracking-[-0.01em] text-balance">
          {title ?? words.title}
        </h3>
      </div>

      {sponsored ? (
        <div className="mx-4 mt-3 grid justify-items-start gap-2 rounded-lg border border-border bg-muted/50 p-3">
          <Badge variant="outline" className="bg-background">
            <IconMegaphone />
            {words.sponsored}
          </Badge>
          <p className="font-medium text-pretty [overflow-wrap:anywhere]">{fill(words.paidBy, { by: sponsored.by })}</p>
          <p className="-mt-1 text-[0.8125rem] leading-relaxed text-pretty text-muted-foreground">{sponsored.note ?? words.sponsoredNote}</p>
        </div>
      ) : null}

      <div className="px-4 pt-4 pb-4">
        <h4 className="text-xs font-medium text-muted-foreground">{sponsored ? words.reasonsSponsored : words.reasons}</h4>
        {reasons.length ? (
          <ul className="mt-3 grid gap-3">
            {reasons.map((reason) => {
              // A kind that is not one of ours (data from elsewhere) is read as the page it is on, rather than taking the panel down.
              const kind: ReasonKind = reason.kind && reason.kind in KIND_ICON ? reason.kind : "context";
              const Icon = KIND_ICON[kind];
              return (
                <li key={`${kind}-${reason.label}`} className="grid grid-cols-[1.75rem_minmax(0,1fr)] items-start gap-x-3">
                  <span aria-hidden="true" className="grid size-7 place-items-center rounded-md bg-muted text-muted-foreground [&_svg]:size-4">
                    <Icon />
                  </span>
                  <div className="min-w-0 pt-px">
                    <p className="leading-snug font-medium text-pretty [overflow-wrap:anywhere]">
                      <span className="sr-only">{kinds[kind]}: </span>
                      {reason.label}
                    </p>
                    {reason.detail ? <p className="mt-0.5 text-[0.8125rem] leading-snug text-pretty text-muted-foreground [overflow-wrap:anywhere]">{reason.detail}</p> : null}
                  </div>
                </li>
              );
            })}
          </ul>
        ) : (
          <p className="mt-2 leading-snug text-pretty text-muted-foreground">{words.noReasons}</p>
        )}
      </div>

      {hasActions ? (
        <div className="grid gap-0.5 border-t border-border p-1.5">
          {onLessLikeThis ? (
            <ActionRow icon={<IconThumbsDown />} label={words.lessLikeThis} done={words.lessDone} phase={less} onPress={() => void run(onLessLikeThis, less, setLess, words.lessDone)} />
          ) : null}
          {onHide ? <ActionRow icon={<IconEyeOff />} label={words.hide} done={words.hideDone} phase={hidden} onPress={() => void run(onHide, hidden, setHidden, words.hideDone)} /> : null}
          {settingsHref ? (
            <a href={settingsHref} className={ROW}>
              <span aria-hidden="true" className="grid size-4 place-items-center text-muted-foreground">
                <IconSliders />
              </span>
              <span className="min-w-0 flex-1 leading-snug">{words.manage}</span>
              <IconChevronRight aria-hidden="true" className="text-muted-foreground transition-transform duration-150 group-hover/row:translate-x-0.5 motion-reduce:transition-none" />
            </a>
          ) : null}
          {problem ? (
            <p role="alert" className={cn("flex items-start gap-2 px-2 pt-1.5 pb-0.5 text-[0.8125rem] leading-snug", DANGER_TEXT)}>
              <IconAlertCircle aria-hidden="true" className="mt-px size-4 shrink-0" />
              <span className="min-w-0">{problem}</span>
            </p>
          ) : null}
        </div>
      ) : null}

      <p role="status" className="sr-only">
        {said}
      </p>
      {/* Last in the DOM, like the close button of a Dialog: the first Tab lands on the first action. Drawn first, in a frame with no height that sticks to the top of whatever scrolls, so a panel taller than the screen keeps its way out in view. */}
      {close ? (
        <div className="sticky top-0 z-10 order-first h-0">
          {/* The bigger button of a touch screen keeps the centre of the small one, so it never reaches down over what is under the title. */}
          <div className="absolute top-2.5 right-2.5 pointer-coarse:top-1.5 pointer-coarse:right-1.5">{close}</div>
        </div>
      ) : null}
    </div>
  );
}

/**
 * The words and the small decisions behind RecommendationReasonPopover, as plain
 * types and functions: they hold no state and call no hook, so a Server
 * Component can use them too.
 */

/** What kind of signal a reason comes from. It picks the icon and is read out before the reason. */
export type ReasonKind = "activity" | "interest" | "popular" | "location" | "similar" | "following" | "context";

/** One reason an item was shown, in plain words. */
export interface RecommendationReason {
  /** The reason as a sentence a person would say: "You viewed Trail running shoes yesterday". */
  label: string;
  /** More, in a smaller line: "Based on what you looked at in the last 7 days". */
  detail?: string;
  /** Where the signal comes from. It picks the icon and says so to screen readers. Default "context". */
  kind?: ReasonKind;
}

/** Who paid for something that is shown as an ad. */
export interface Sponsorship {
  /** The advertiser: "Northwind Outfitters". */
  by: string;
  /** What sponsorship means here, in a sentence. Without it the panel says what the labels default to. */
  note?: string;
}

/** The words the popover says, for translation. `{by}` is filled in. */
export interface RecommendationReasonLabels {
  /** The title, and the name of the default button. Default "Why am I seeing this?" */
  title?: string;
  /** The close button's name. Default "Close". */
  close?: string;
  /** The word on an ad. Default "Sponsored". */
  sponsored?: string;
  /** Who paid. Default "Paid for by {by}". */
  paidBy?: string;
  /** What sponsorship means, when `sponsored.note` is not given. Default "Advertisers pay to reach people who may like what they offer. They do not get your name or what you do here." */
  sponsoredNote?: string;
  /** The heading over the reasons of something recommended. Default "Why it was chosen for you". */
  reasons?: string;
  /** The heading over the reasons of an ad. Default "Why this ad was shown to you". */
  reasonsSponsored?: string;
  /** What is said when there are no reasons to give. Default "This was not chosen using anything we know about you." */
  noReasons?: string;
  /** Said to screen readers in front of each reason, by the kind of signal. */
  kinds?: Partial<Record<ReasonKind, string>>;
  /** The button that asks for less of this. Default "Show less like this". */
  lessLikeThis?: string;
  /** What that button says once it worked. Default "We will show you less like this". */
  lessDone?: string;
  /** The button that hides the item. Default "Hide this". */
  hide?: string;
  /** What that button says once it worked. Default "Hidden. You will not see this again". */
  hideDone?: string;
  /** The link to the settings. Default "Manage personalisation". */
  manage?: string;
  /** Said while an action is being saved. Default "Saving". */
  saving?: string;
  /** Shown and said when an action failed. Default "Could not save that. Nothing was changed." */
  failed?: string;
}

export const DEFAULT_KINDS = {
  activity: "Your activity",
  interest: "Your interests",
  popular: "Popular",
  location: "Where you are",
  similar: "People like you",
  following: "What you follow",
  context: "This page",
} satisfies Record<ReasonKind, string>;

export const DEFAULT_LABELS = {
  title: "Why am I seeing this?",
  close: "Close",
  sponsored: "Sponsored",
  paidBy: "Paid for by {by}",
  sponsoredNote: "Advertisers pay to reach people who may like what they offer. They do not get your name or what you do here.",
  reasons: "Why it was chosen for you",
  reasonsSponsored: "Why this ad was shown to you",
  noReasons: "This was not chosen using anything we know about you.",
  lessLikeThis: "Show less like this",
  lessDone: "We will show you less like this",
  hide: "Hide this",
  hideDone: "Hidden. You will not see this again",
  manage: "Manage personalisation",
  saving: "Saving",
  failed: "Could not save that. Nothing was changed.",
} satisfies Omit<Required<RecommendationReasonLabels>, "kinds">;

/** Puts values into a template: `fill("Paid for by {by}", { by: "Northwind" })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? (values[key] ?? match) : match));
}

/** Whether a handler returned a promise, so a quick answer does not flash a busy state. */
export function isThenable(value: unknown): value is PromiseLike<unknown> {
  return typeof value === "object" && value !== null && typeof (value as { then?: unknown }).then === "function";
}

/** The message a refused action carries, when it carries one worth showing: an `Error` with text. */
export function messageOf(error: unknown): string {
  return error instanceof Error ? error.message.trim() : "";
}
